def _quitar_unicos_user_pais(apps, schema_editor):
    """Borra restricciones o índices únicos exactamente sobre (user_id, pais_id)."""
    conn = schema_editor.connection
    for model_name in ("ChainOwnerPaisRole", "CountryAdminScope"):
        table = apps.get_model("reservas", model_name)._meta.db_table
        with conn.cursor() as cur:
            cons = conn.introspection.get_constraints(cur, table)
        for name, info in cons.items():
            if not info.get("unique") or info.get("primary_key"):
                continue
            if sorted(info.get("columns") or []) != ["pais_id", "user_id"]:
                continue
            qn = schema_editor.quote_name
            with conn.cursor() as cur:
                # ¿Es una restricción (pg_constraint) o solo un índice único?
                es_constraint = True
                if conn.vendor == "postgresql":
                    cur.execute(
                        "SELECT 1 FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid "
                        "WHERE t.relname = %s AND c.conname = %s", [table, name]
                    )
                    es_constraint = cur.fetchone() is not None
                if es_constraint:
                    cur.execute(f"ALTER TABLE {qn(table)} DROP CONSTRAINT IF EXISTS {qn(name)}")
                else:
                    cur.execute(f"DROP INDEX IF EXISTS {qn(name)}")



